<p class="eyebrow"><?= $e($t('PRIVATE · EMAIL UPDATES')) ?></p><h1><?= $e($t('Notification delivery')) ?></h1><p class="notice"><?= $e($t($mailEnabled?'Email delivery is enabled. Accepted by the mail server does not guarantee arrival in the inbox.':'Email delivery is disabled. Requests still have private tracking links. Configure the mailbox in the private site settings before sending queued updates.')) ?></p><p><?= $e($t('Only requesters who chose email updates receive these messages. Pending updates remain queued. Retry attempts are limited to five per message; ambiguous mail-server failures can result in duplicate delivery.')) ?></p><?php foreach ($jobs as $job): ?><article class="card"><span class="badge"><?= $e($job['state']!=='SENT' && !$job['fresh'] ? $t('Expired · private link is no longer current') : $job['state']) ?></span><h2><?= $e($job['subject']) ?></h2><p><?= $e($job['recipient']) ?> · <?= $e($job['created_at']) ?> UTC</p><p><?= $e($t('Attempts')) ?>: <?= $e($job['attempts']) ?>/5</p><?php if ($mailEnabled && $job['state']!=='SENT' && $job['fresh'] && (int)$job['attempts']<5): ?><form data-api="/api/notifications/<?= $e($job['id']) ?>/retry" data-reload><button class="button secondary"><?= $e($t('Send or retry update')) ?></button><p class="form-message" role="status"></p></form><?php endif ?></article><?php endforeach ?><?php if (!$jobs): ?><p class="empty"><?= $e($t('No email updates have been queued for your communities.')) ?></p><?php endif ?>
